parameters.text:
=You are an expert social media copywriter and growth marketer.

Create a high-performing social media post draft based on these campaign parameters:
- Topic: {{ $json.topic }}
- Target Platform: {{ $json.platform }}
- Target Audience: {{ $json.audience }}
- Desired Tone: {{ $json.tone }}

IMPORTANT REQUIREMENTS:
1. Tailor formatting, hooks, emojis, and length specifically for the platform ({{ $json.platform }}).
2. Culturally resonate with the audience ({{ $json.audience }}).
3. You MUST respond with ONLY a valid raw JSON object. Do not wrap in markdown codeblocks (no ```json or ```). No preface, conversational filler, or commentary.

JSON Schema:
{
  "caption": "Complete post caption with engaging hook and emojis",
  "hashtags": "#hashtag1 #hashtag2 #hashtag3 #hashtag4 #hashtag5",
  "call_to_action": "Clear, high-converting call to action tailored to the platform"
}

parameters.jsCode:
// Extract incoming LLM output and campaign parameters
const inputItem = $input.first();
const originalParams = $('Define Campaign Parameters').first().json;

// Basic LLM Chain outputs the generated text under 'text' or 'response'
let rawText = inputItem.json.text || inputItem.json.response || '';

// Clean markdown fences if the model returned ```json ... ```
if (typeof rawText === 'string') {
  rawText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
}

let parsed = {};
try {
  parsed = typeof rawText === 'object' ? rawText : JSON.parse(rawText);
} catch (error) {
  // Resilient fallback in case the model returned freeform text instead of strict JSON
  parsed = {
    caption: rawText.trim(),
    hashtags: '#Promotion #SpecialOffer',
    call_to_action: 'Check out our latest update!'
  };
}

// Construct the normalized 9-field output record
const record = {
  created_at: new Date().toISOString(),
  topic: originalParams.topic || 'New pizza promotion',
  platform: originalParams.platform || 'Instagram',
  audience: originalParams.audience || 'Young adults in Addis Ababa',
  tone: originalParams.tone || 'Friendly and engaging',
  caption: parsed.caption || '',
  hashtags: parsed.hashtags || '',
  call_to_action: parsed.call_to_action || '',
  status: 'Draft - Review Required'
};

return [{ json: record }];
